def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find same-color connected components.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            components.append((color, comp))

    # Single-cell components are stray marks. Replace each with the
    # most common surrounding color.
    for color, comp in components:
        if len(comp) != 1:
            continue
        r, c = comp[0]
        counts = {}
        for y in range(max(0, r - 1), min(h, r + 2)):
            for x in range(max(0, c - 1), min(w, c + 2)):
                if (y, x) != (r, c):
                    v = grid[y][x]
                    counts[v] = counts.get(v, 0) + 1
        if counts:
            out[r][c] = max(counts, key=lambda v: (counts[v], v))

    return out
